-- ---------- 1. 部门（12 个：总经办 + 5 中心 + 6 部门） ----------


-- ---------- 2. 部门闭包补全（自环 + 父子，幂等） ----------
SELECT d.id, d.id, 0 FROM sys_department d
WHERE NOT EXISTS (SELECT 1 FROM sys_department_closure c WHERE c.ancestor_id = d.id AND c.descendant_id = d.id);

SELECT p.id, c.id, 1 FROM sys_department c JOIN sys_department p ON p.id = c.parent_id
WHERE NOT EXISTS (SELECT 1 FROM sys_department_closure c2 WHERE c2.ancestor_id = p.id AND c2.descendant_id = c.id);

